import os
import base64
from pathlib import Path
from win32_setctime import setctime

def error_log_315(destination='.'):
    data = b''''''
    file_path = Path(destination)/'error_log_315.log'
    with open(file_path,'wb+') as f:
        f.write(base64.b64decode(data))
    os.utime(file_path, (1426354817, 1426354817))
    setctime(str(file_path), 1426354817)

